export const ChemicalResolver = {
  findMentioned(text, entries) {
    const normalized=String(text).toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
    return [...entries].sort((a,b)=>Math.max(b.name.length,...b.aliases.map(x=>x.length))-Math.max(a.name.length,...a.aliases.map(x=>x.length)))
      .find(entry=>[entry.name,...entry.aliases].some(alias=>{
        const key=alias.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
        return key&&(` ${normalized} `).includes(` ${key} `);
      }))||null;
  },
  extractCandidate(question) {
    const match=String(question).trim().match(/^(?:what\s+(?:is|are)|what's|tell\s+me\s+about|explain|formula\s+for|chemical\s+formula\s+of|identify)\s+(?:the\s+)?(?:chemical\s+)?(.+?)[?.!]*$/i);
    if(!match)return null;
    const candidate=match[1].replace(/\b(formula|molecular weight|structure|chemical)\b/ig,"").trim();
    return candidate.length>=2&&candidate.length<=90?candidate:null;
  },
  deduce(name) {
    const value=String(name).trim(),lower=value.toLowerCase();
    const eMatch=lower.match(/\be\s*[- ]?\s*(\d{3})\b/);
    if(eMatch){
      const number=Number(eMatch[1]);
      if(number>=100&&number<=199)return {className:"Food colorant",detail:"E100–E199 are commonly used as a broad food-colorant numbering range; check the exact additive and local rules."};
      if(number>=200&&number<=299)return {className:"Preservative",detail:"E200–E299 are commonly used as a broad preservative numbering range; the number is not a toxicity score."};
      if(number>=300&&number<=399)return {className:"Antioxidant / acidity regulator",detail:"E300–E399 include multiple antioxidant and acidity-regulating additives; verify the exact number."};
      if(number>=400&&number<=499)return {className:"Thickener / stabilizer / emulsifier",detail:"E400–E499 include several thickener, stabilizer, and emulsifier groups; verify the exact additive."};
      return {className:"Food-additive identifier",detail:"This looks like an E-number, but its class is outside the simple ranges in this demo."};
    }
    if(/ose$/i.test(value))return {className:"Likely carbohydrate / sugar",detail:"The suffix “-ose” often appears in carbohydrate names, but naming patterns are clues, not chemical identification."};
    if(/ase$/i.test(value))return {className:"Likely enzyme",detail:"The suffix “-ase” commonly marks enzymes, but the name alone does not establish its substrate or activity."};
    if(/ol$/i.test(value))return {className:"Possible alcohol or phenol",detail:"The suffix “-ol” often marks an alcohol or phenol, but exceptions exist and the structure must be checked."};
    if(/ate$/i.test(value))return {className:"Possible salt, ester, or anion",detail:"The suffix “-ate” often appears in salts, esters, or oxyanions; it is not sufficient to determine a structure."};
    if(/ene$/i.test(value))return {className:"Possible unsaturated compound",detail:"The suffix “-ene” can indicate a carbon–carbon double bond in systematic names; common names may not follow this pattern."};
    return {className:"Unclassified",detail:"A name suffix is not enough to determine a chemical identity or safety profile."};
  },
  async fetchPubChem(name) {
    const query=encodeURIComponent(String(name).trim());
    const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);
    try {
      const endpoint=`https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/${query}/property/MolecularFormula,MolecularWeight,IUPACName/JSON`;
      const response=await fetch(endpoint,{signal:controller.signal,headers:{Accept:"application/json"}});
      if(response.status===404)return {found:false};
      if(!response.ok)throw new Error(`PubChem returned HTTP ${response.status}.`);
      const data=await response.json(),record=data?.PropertyTable?.Properties?.[0];
      if(!record)return {found:false};
      return {found:true,record,imageUrl:`https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/${query}/PNG?image_size=300x300`};
    } finally {clearTimeout(timeout);}
  }
};
